const fleet1985 = "<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Registered branch</th><th>Current 1985 position</th></tr></thead><tbody><tr><td>Large guided-weapon ships</td><td>Wotan and Siegfried active</td></tr><tr><td>Light carriers</td><td>Europa and Hansa active</td></tr><tr><td>Missile cruisers</td><td>Six Admiral Scheer-class ships active</td></tr><tr><td>Destroyers</td><td>Role and development sequence retained as working reconstruction; exact classes and totals open</td></tr><tr><td>Frigates</td><td>Role and development sequence retained as working reconstruction; exact classes and totals open</td></tr><tr><td>Fast combatants</td><td>Coastal missile-combatant branch retained; exact classes and totals open</td></tr><tr><td>Submarines</td><td>World-leading fast, AIP ambush, nuclear attack, guided-missile, and transport system; exact postwar totals open</td></tr><tr><td>Other support categories</td><td>Amphibious, mine-warfare, auxiliary, and complete readiness totals open</td></tr></tbody></table></div>";

const submarineTable = "<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Type or school</th><th>First major period</th><th>Governing design priority</th><th>Registered position</th></tr></thead><tbody><tr><td>Type XXI</td><td>1944 onward</td><td>General ocean Elektroboot and fully submerged operations</td><td>Wartime mass-operational foundation</td></tr><tr><td>Type XXVI</td><td>1945–47</td><td>Walter high-performance escort hunter</td><td>Elite, scarce, and technically secret</td></tr><tr><td>Type XXV</td><td>1946–47 trials</td><td>Teardrop hull, extreme submerged sprint, and maneuverability</td><td>Battery-limited fast-school ancestor</td></tr><tr><td>Type XXIV A</td><td>c. 1951</td><td>Acoustic discipline, passive sensing, and ambush patrol</td><td>Conventional stealth-school founder</td></tr><tr><td>Type XXIV B / Versuch</td><td>c. 1954–56</td><td>Inserted Stirling AIP plant</td><td>First German naval Stirling demonstrator</td></tr><tr><td>Type XXIX</td><td>c. 1959–61</td><td>Purpose-designed Stirling AIP seabed ambush</td><td>Mature Lauerboot school</td></tr><tr><td>Type XXX</td><td>c. 1962</td><td>Nuclear endurance joined to fast-school hydrodynamics and quieting</td><td>Nuclear Jagd-U-Boot school</td></tr><tr><td>Type XXXI and later derivatives</td><td>Late 1960s onward</td><td>Submerged conventional guided-missile attack</td><td>Concealed bombardment school</td></tr></tbody></table></div>";

Object.assign(window.deepArticles, {
  "kriegsmarine-postwar": navalArticle({
    title:"Kriegsmarine after the Second World War",
    category:"Military history",
    eyebrow:"German navy · victory, reduction, and technical reconstruction",
    landscape:fleetLandscape,
    lead:"After the Second World War, the Kriegsmarine became the naval arm of a continental empire whose decisive maritime weapon was the submarine rather than the carrier or battleship. It retained a registered surface force to cover Atlantic exits, protect Norway and Iceland, sustain <a href='german-mittelafrika-sea-communications.html'>the Europe–Mittelafrika connection</a>, and display technical power while developing fast, AIP ambush, nuclear attack, guided-missile, and transport submarine schools.",
    canon:"The working 1947 allocation, strategic division of labor, registered surface classes, three complementary first-line submarine design schools, nuclear-propulsion role, conventional-only missile mission, transport branches, and surface-support mission are retained. German armistice totals remain a working reconstruction, and the former exact 1985 submarine, amphibious, mine-warfare, and auxiliary totals are withdrawn; postwar U-boat construction totals, detailed fleet commands, base order, patrol cycles, and individual U-number allocations remain open.",
    sections:[
      {id:"inheritance",title:"Armistice inheritance",html:"<!-- altwwii-writer-block:start id=wb-g-20260815-t3e7l writer=g kind=revision created=2026-08-15T22:31:00-06:00 --><p><em>Bismarck</em> was sunk before divergence and is excluded from the armistice inheritance. The named capital ships are <em>Tirpitz</em>, <em>Scharnhorst</em>, <em>Gneisenau</em>, and <em>Friedrich der Große</em>; the final capital total remains open.<sup class='canon-note' data-provenance='a'>[a]</sup></p><!-- altwwii-writer-block:end --><p>The current working allocation gives Germany two carriers, eleven cruisers, forty-eight destroyers, sixty-four major escorts, and 820 physically extant submarines at the end of 1947. It places 310 U-boats in the front line: 110 Type XXI, forty Type XXIII or related coastal Elektroboote, one hundred modernized Type VII and IX boats, and sixty minelaying, transport, reconnaissance, or special boats.</p><p>The excess fleet supplied crews, machinery, test hulls, exports, training, and scrap. Rapid reduction was therefore part of continuity rather than disarmament.</p>"},
      {id:"strategy",title:"Strategic division of labor",html:"<p>The mature service divided its work among three establishments. The <a href='german-submarine-force.html'>U-boat fleet</a> denied hostile use of the ocean; the escort fleet kept Germany's own Atlantic road open; and the heavy <a href='german-surface-fleet.html'>surface fleet</a> complicated and reinforced both missions. <a href='german-mittelafrika-sea-communications.html'>Mittelafrika's sea connection</a> made the middle function indispensable.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>Germany did not try to equal American or Japanese carrier totals. It sought to make hostile ocean use unsafe while preserving a bounded route to its own overseas empire.</p>"},
      {id:"geography",title:"Bases and geography",html:"<p>Norwegian ports, the Baltic, North Sea yards, Atlantic facilities, and the later German position in Iceland shortened access to patrol areas and complicated hostile barriers. Surface escorts, patrol aircraft, signals stations, satellites, tenders, and disguised maritime sensors supported the boats.</p><p>The base network remained vulnerable to surveillance and conventional attack. Its strength lay in dispersal, protected facilities, repair depth, and uncertainty about which departures represented combat patrols.</p>"},
      {id:"technology",title:"Technology and industry",html:"<p>The Type XXI inheritance made submerged performance the design center. Type XXV and XXVI work explored speed. Type XXIV and Type XXIX developed passive-sensing and Stirling-AIP ambush. Type XXX established the nuclear Jagd-U-Boot, while Type XXXI opened the submerged conventional-missile branch.</p><p>Nuclear power supplied endurance and speed but no nuclear warheads. Missile submarines were concealed conventional bombardment ships rather than an atomic deterrent.</p>"},
      {id:"surface",title:"Surface reconstruction",html:"<!-- altwwii-writer-block:start id=wb-g-20260815-u4f8m writer=g kind=revision created=2026-08-15T22:31:00-06:00 --><p>The inherited battleships and the distinct <em>Friedrich der Große</em> and <em>Großdeutschland</em> programs retired during the postwar transition. <em>Friedrich der Große</em> came from selectively revived H-39 work; <em>Großdeutschland</em> was the separate Yamato-scale prestige project.<sup class='canon-note' data-provenance='a'>[a]</sup> The <a href='german-carrier-force.html'>carrier arm</a> moved from <em>Graf Zeppelin</em> and <em>Peter Strasser</em> to two Europa-class light carriers.</p><!-- altwwii-writer-block:end --><p>Six <a href='admiral-scheer-class.html'>Admiral Scheer-class cruisers</a> and two <a href='wotan-class.html'>Wotan-class large guided-weapon ships</a> supplied command, missiles, aviation, and visible prestige.</p>"},
      {id:"1985",title:"Fleet in 1985",html:"<!-- altwwii-writer-block:start id=wb-g-20260815-j8c4r writer=g kind=revision created=2026-08-15T14:00:00-06:00 -->"+fleet1985+"<p>The table distinguishes fixed class registers from the withdrawn all-category ledger. It does not convert known classes into a complete readiness or deployment total.</p><!-- altwwii-writer-block:end -->"},
      {id:"assessment",title:"Strategic assessment",html:"<p>Foreign governments could observe yards, budgets, launches, and bases but struggled to establish readiness, patrol state, conversion status, or whether repeated similar acoustic contacts represented the same boat. This uncertainty was a designed military effect.</p><p>The fleet's limit was equally real: submarines required intelligence, communications, maintenance, weapons, trained crews, and protected access. A submarine-centered navy was not an invisible or self-sufficient one.</p>"}
    ],
    related:[{href:"world-naval-balance-1985.html",kicker:"Comparative strength",label:"World Naval Balance in 1985"},{href:"naval-armistice-inventory-1947.html",kicker:"Five-navy comparison",label:"Naval Armistice Inventory of 1947"},{href:"german-armistice-fleet.html",kicker:"National inheritance",label:"German Armistice Fleet"},{href:"german-submarine-force.html",kicker:"Principal striking arm",label:"German Submarine Force"},{href:"german-surface-fleet.html",kicker:"Supporting fleet",label:"German Surface Fleet"},{href:"german-mittelafrika-sea-communications.html",kicker:"Positive sea-lane mission",label:"German–Mittelafrika Sea Communications"},{href:"german-africa-naval-station.html",kicker:"Southern route establishment",label:"German Africa Naval Station"},{href:"german-atlantic-facilities-brittany.html",kicker:"Western base network",label:"German Atlantic Facilities in Brittany"},{href:"germany.html",kicker:"Sovereign power",label:"Greater German Reich"}],
    facts:[["Service","Kriegsmarine"],["Strategic center","U-boat force"],["1947 submarines afloat","820 working"],["1947 front-line submarines","310 working"],["1985 submarine position","World-leading; exact totals open"],["1985 carriers","Europa and Hansa"],["Nuclear weapons","None"],["Reference date","1 January 1985"]]
  }),

  "german-surface-fleet": navalArticle({
    title:"German surface fleet, 1947–1985",
    landscape:fleetLandscape,
    lead:"The German surface fleet was the visible and supporting arm of the postwar Kriegsmarine. Its carriers, cruisers, destroyers, frigates, missile craft, mine forces, amphibious ships, and auxiliaries defended the exits used by German submarines, protected <a href='german-mittelafrika-sea-communications.html'>the Europe–Mittelafrika route</a>, and forced hostile fleets to account for a second attack axis. The service did not seek numerical symmetry with the American or Japanese carrier systems: surface formations existed to make concealed attack more effective and to keep Germany's own ocean road open.",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-sf4kl writer=g kind=revision created=2026-08-16T08:23:53-06:00 -->The submarine-centered division of labor, continued but bounded carrier institution, retirement of the gun capital ships, fixed 1985 Wotan, Europa, and Admiral Scheer classes, Europe–Mittelafrika mission, and surface contribution to the German detection-to-attack network are established.<sup class='canon-note' data-provenance='a'>[a]</sup> Exact destroyer, frigate, fast-combatant, mine-warfare, amphibious, auxiliary, readiness, command, base, deployment, and complete refit totals remain open pending registry reconstruction.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"settlement",title:"The postwar institutional settlement",html:"<p>Raeder's construction program left Germany with battleships, carriers, cruisers, dockyards, naval aviation, and a professional surface officer corps. Dönitz's school nevertheless controlled the postwar burden of proof: a new surface ship had to explain what it contributed to the undersea-centered war.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>This did not reduce surface officers to ceremonial service. It redirected their institution toward air defense, command, reconnaissance, escort, mine warfare, and the creation of tactical problems that opened routes for submarines.</p>"},
      {id:"missions",title:"Strategic missions",html:"<p>Surface forces protected North Sea, Baltic, Norwegian, Icelandic, and Atlantic approaches; escorted replenishment and military shipping; defended submarine bases and deployment lanes; and maintained the <a href='german-mittelafrika-sea-communications.html'>Europe–Mittelafrika connection</a>. Client support, patrol, and diplomatic presence extended those functions without turning the fleet into a general ocean-control navy.</p><p>Its operating logic was geographical. Near German and associated bases, ships could combine land aviation, coastal radar, mines, Schnellboote, escorts, and submarines. Farther at sea, every formation depended increasingly upon reconnaissance, replenishment, and disciplined emissions control.</p>"},
      {id:"periods",title:"Development periods",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Period</th><th>Principal development</th><th>Surface-fleet result</th></tr></thead><tbody><tr><td>1948–1958</td><td>Rationalization of the victory fleet</td><td>Selected inherited construction completed; obsolete hulls reduced; carrier, escort, and guided-weapon institutions retained</td></tr><tr><td>1958–1970</td><td>Underwater technological revolution</td><td>Gun capital ships age; missile escorts and command cruisers replace the battle line as the practical surface center</td></tr><tr><td>1970–1985</td><td>Missile-network fleet</td><td>Vertical launch, helicopters, digital combat direction, and distributed targeting connect surface groups to the submarine system</td></tr></tbody></table></div><p>The periods describe institutional emphasis rather than clean breaks. Older ships, crews, and procedures overlapped each transition.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"capital",title:"From gun capital ships to guided-weapon ships",html:"<!-- altwwii-writer-block:start id=wb-g-20260815-v5g9n writer=g kind=revision created=2026-08-15T22:31:00-06:00 --><p><em>Bismarck</em> was lost before divergence. <em>Tirpitz</em>, <em>Friedrich der Große</em>, and <em>Großdeutschland</em> retired in 1968, 1972, and 1975; the latter two were distinct designs rather than sister H-39 completions.<sup class='canon-note' data-provenance='a'>[a]</sup> Germany did not begin a replacement armored battle line.</p><!-- altwwii-writer-block:end --><p><a href='wotan-class.html'>Wotan</a> and <em>Siegfried</em> instead concentrated command spaces, long-range air defense, conventional land attack, aviation, and a deep missile magazine in ships officially designated <em>Große Lenkwaffenschiffe</em>.</p>"},
      {id:"carriers",title:"Carrier arm",html:"<p>The <a href='graf-zeppelin-and-peter-strasser.html'><em>Graf Zeppelin</em> and <em>Peter Strasser</em> generation</a> created a permanent but limited deck-aviation institution. The second ship was a new post-divergence design oriented toward turbine aircraft rather than a simple sister of the prewar hull; its final wartime completion chronology remains open.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>The <a href='europa-class-light-carrier.html'>Europa-class light carriers</a>, <em>Europa</em> and <em>Hansa</em>, commissioned in 1962 and 1966 and remained the two registered active carriers in 1985. Their reconnaissance, fighter, and helicopter capacity served surface and submarine operations rather than an independent mass-strike doctrine.</p>"},
      {id:"cruisers",title:"Cruisers and command ships",html:"<p>Six <a href='admiral-scheer-class.html'>Admiral Scheer-class missile cruisers</a> commissioned between 1968 and 1976. They supplied the routine task-group center: radar volume, command facilities, helicopters, 150 mm guns, heavy anti-ship weapons, and sixty-four vertical cells.</p><p>The 1974 public presentation of <em>Admiral Scheer</em> disclosed surface vertical-launch and guidance architecture derived from work already conducted for submerged missile boats. It made the surface fleet the public face of technology developed within the less visible striking arm.</p>"},
      {id:"escorts",title:"Escorts and coastal combatants",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-sf5lm writer=g kind=revision created=2026-08-16T08:23:53-06:00 --><p><a href='german-surface-escorts.html'>Destroyers and frigates</a> covered the approaches in which German submarines were most exposed. The working class register assigns fleet defense to Typ 64 and Typ 76 destroyers, submarine search and route protection to Typ 62 and Typ 74 frigates, and coastal missile-and-surveillance work to Typ 73 Schnellboote. Exact 1985 escort and fast-combatant totals are open.</p><p>Mine forces and shore sensors extended the same denial system, but their complete class and readiness registers also remain open.</p><!-- altwwii-writer-block:end -->"},
      {id:"network",title:"Detection and attack network",html:"<p>Long-range patrol aircraft, carrier reconnaissance, electronic surveillance, satellites, shore stations, surface radar, and submarines contributed to a common operational chain: detect, classify, track, distribute, and attack. A long-range missile without a current target position had little value; a surface radar picture that could not reach a concealed attacker had limited offensive effect.</p><p>The network therefore mattered as much as any individual launcher. Surface groups could reveal, confirm, relay, or deliberately threaten while submarines maneuvered against the resulting defensive response.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
      {id:"fleet-action",title:"Fleet employment",html:"<p>A mature German operation did not normally begin with a large ship seeking a decisive duel. Reconnaissance established the contact area, submarines covered likely routes, and a surface group advanced far enough to demand fighter, missile-defense, and surveillance attention. That pressure could divide hostile antisubmarine effort before any German surface missile was fired.</p><p>A Wotan- or Admiral Scheer-centered group could attack directly, but its deeper purpose was to complicate the opponent's geometry and preserve the initiative for concealed weapons.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"balance",title:"Registered surface balance in 1985",html:"<!-- altwwii-writer-block:start id=wb-g-20260815-u6c2h writer=g kind=revision created=2026-08-15T14:10:00-06:00 --><div class='table-wrap'><table class='wiki-table'><thead><tr><th>Branch</th><th>Fixed or working position</th><th>Classes</th></tr></thead><tbody><tr><td>Large guided-weapon ships</td><td>2 fixed</td><td>Wotan class</td></tr><tr><td>Light carriers</td><td>2 fixed</td><td>Europa class</td></tr><tr><td>Missile cruisers</td><td>6 fixed</td><td>Admiral Scheer class</td></tr><tr><td>Destroyers</td><td>Exact total open</td><td>Typ 64 and Typ 76 working register</td></tr><tr><td>Frigates</td><td>Exact total open</td><td>Typ 62 and Typ 74 working register</td></tr><tr><td>Fast combatants</td><td>Exact total open</td><td>Typ 73 Schnellboot working register</td></tr></tbody></table></div><p>The revised naval audit fixes the major surface classes but withdraws the former all-category total. Escort, fast-combatant, amphibious, mine-warfare, auxiliary, reserve, and readiness counts require registry reconstruction.</p><!-- altwwii-writer-block:end -->"},
      {id:"limits",title:"Limits and assessment",html:"<p>Germany lacked a carrier force capable of matching Japan or the United States ship for ship. A surface group beyond land aviation, submarine support, and established logistics remained vulnerable to concentrated carrier attack.</p><p>The fleet was most dangerous where it could combine missiles, submarines, aircraft, mines, and protected geography. Its strength was not an invulnerable ship; it was the number of mutually supporting problems an opponent had to solve at once.</p>"}
    ],
    related:[{href:"kriegsmarine-postwar.html",kicker:"Parent service",label:"Postwar Kriegsmarine"},{href:"german-capital-ships-postwar.html",kicker:"Heavy-ship transition",label:"German Capital Ships after 1947"},{href:"german-carrier-force.html",kicker:"Naval aviation",label:"German Carrier Force"},{href:"wotan-class.html",kicker:"Heavy command ships",label:"Wotan Class"},{href:"admiral-scheer-class.html",kicker:"Cruiser lineage",label:"Admiral Scheer Class"},{href:"german-surface-escorts.html",kicker:"Destroyers and frigates",label:"German Surface Escorts"},{href:"german-mittelafrika-sea-communications.html",kicker:"Positive sea-lane mission",label:"German–Mittelafrika Sea Communications"}],
    facts:[["Doctrine","Support submarine access and impose visible threat"],["Large guided-weapon ships, 1985","2"],["Light carriers, 1985","2"],["Cruisers, 1985","6"],["Escort and fast-combatant totals","<!-- altwwii-writer-block:start id=wb-g-20260816-sf7np writer=g kind=revision created=2026-08-16T08:23:53-06:00 -->Open pending registry reconstruction<!-- altwwii-writer-block:end -->"]]
  }),

  "german-capital-ships-postwar": navalArticle({
    title:"German capital ships after 1947",
    category:"Warship history",
    landscape:fleetLandscape,
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260815-w6h2p writer=g kind=revision created=2026-08-15T22:31:00-06:00 -->German capital-ship history after 1947 was the managed retirement of the surviving victory fleet's battleships and their replacement by large missile-and-command ships rather than a new armored gun line. <em>Tirpitz</em>, <em>Friedrich der Große</em>, and <em>Großdeutschland</em> remained potent symbols, while <em>Bismarck</em> was irretrievably lost before the 1 August 1941 divergence.<sup class='canon-note' data-provenance='a'>[a]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260815-x7i3q writer=g kind=revision created=2026-08-15T22:31:00-06:00 -->The pre-divergence loss of <em>Bismarck</em>, inherited survival of <em>Tirpitz</em>, <em>Scharnhorst</em>, and <em>Gneisenau</em>, separate identities of the H-39-derived <em>Friedrich der Große</em> and Yamato-scale <em>Großdeutschland</em>, stated commissioning and retirement years, Wotan succession, and doctrinal shift are established.<sup class='canon-note' data-provenance='a'>[a]</sup><!-- altwwii-writer-block:end --> Postwar refit details, the final German 1947 capital total, the later dispositions of <em>Scharnhorst</em> and <em>Gneisenau</em>, reserve periods, ceremonial dispositions, museum status, and individual operational cruises remain open.",
    sections:[
      {id:"inheritance",title:"Victory-fleet inheritance",html:"<!-- altwwii-writer-block:start id=wb-g-20260815-y8j4r writer=g kind=revision created=2026-08-15T22:31:00-06:00 --><p><em>Bismarck</em> sank on 27 May 1941 and never entered the alternate postwar fleet. <em>Tirpitz</em>, <em>Scharnhorst</em>, and <em>Gneisenau</em> survived into the divergent war. <em>Friedrich der Große</em> completed the selectively revived H-39 program in 1947, while <em>Großdeutschland</em> commissioned in 1949 as a separate Yamato-scale prestige design.<sup class='canon-note' data-provenance='a'>[a]</sup></p><!-- altwwii-writer-block:end --><p>The result was not one homogeneous class line. It was a mixed inheritance of prewar ships, wartime completions, and one politically protected prestige project.</p>"},
      {id:"politics",title:"Raeder, Dönitz, and the burden of proof",html:"<p>The heavy ships survived because construction, yards, officers, and public prestige were already invested in them when Germany won. Postwar submarine predominance changed the standard applied to any successor: a large surface ship had to provide more than symbolic continuity.</p><p>No further armored battle line met that standard. Command, missile defense, aviation, and long-range conventional attack did.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
      {id:"ships",title:"Established ship register",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Ship</th><th>Origin</th><th>Established postwar position</th></tr></thead><tbody><tr><td><em>Tirpitz</em></td><td>Bismarck class</td><td>Retired 1968</td></tr><tr><td><em>Scharnhorst</em></td><td>Scharnhorst class</td><td>Later disposition open</td></tr><tr><td><em>Gneisenau</em></td><td>Scharnhorst class</td><td>Later disposition open</td></tr><tr><td><em>Friedrich der Große</em></td><td>H-39-derived completion</td><td>Commissioned 1947; retired 1972</td></tr><tr><td><em>Großdeutschland</em></td><td>Separate Yamato-scale prestige project</td><td>Commissioned 1949; retired 1975</td></tr></tbody></table></div>"},
      {id:"roles",title:"Postwar roles",html:"<p>The heavy ships served as fleet-command platforms, coastal-bombardment assets, concentration points, training ships, diplomatic instruments, and symbols of wartime victory. Their guns remained destructive, but aircraft and guided weapons increasingly determined whether a ship could approach firing range.</p><p>They were therefore retained as usable inherited assets rather than as templates for a permanent construction policy.</p>"},
      {id:"modernization",title:"Modernization problem",html:"<p>Radar, communications, antiaircraft defense, electronic warfare, and guided weapons could extend the usefulness of an old heavy hull. They could not cheaply transform its machinery, protection geometry, crew burden, or aviation arrangements into those of a purpose-designed missile command ship.</p><p>Exact refit packages remain open. The established retirement sequence is more secure than any proposed catalog of postwar alterations.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"retirement",title:"Retirement sequence",html:"<!-- altwwii-writer-block:start id=wb-g-20260815-z9k5s writer=g kind=revision created=2026-08-15T22:31:00-06:00 --><p><em>Tirpitz</em> retired in 1968, <em>Friedrich der Große</em> in 1972, and <em>Großdeutschland</em> in 1975. The staggered withdrawals released crews, dock time, and operating funds for submarines, escorts, missiles, and naval aviation without staging a single political repudiation of the victory fleet.<sup class='canon-note' data-provenance='a'>[a]</sup></p><!-- altwwii-writer-block:end --><p>The later dispositions of <em>Scharnhorst</em> and <em>Gneisenau</em> remain open.</p>"},
      {id:"gap",title:"The post-battleship gap",html:"<p>After 1975 Germany lacked a serving armored gun capital ship. The absence was deliberate: surface officers still wanted a large command centerpiece, but the Navy would not finance another ship whose principal claim was very heavy guns and armor.</p><p>The solution emerged from technologies already justified elsewhere—nuclear propulsion, vertical launch, long-range radar, helicopters, electronic warfare, and conventional land-attack missiles.</p>"},
      {id:"successor",title:"The Wotan solution",html:"<p><a href='wotan-class.html'><em>Wotan</em> and <em>Siegfried</em></a> commissioned in 1978 and 1982. Each displaced 28,000 tonnes full load and carried four 150 mm guns, ninety-six missile cells, and three helicopters around extensive command spaces and a nuclear-electric plant.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>Official classification as <em>Großes Lenkwaffenschiff</em> emphasized function rather than lineage. The ships inherited the prestige and command role of the battle line without claiming battleship armor or a gun-duel mission.</p>"},
      {id:"comparison",title:"Continuity and discontinuity",html:"<p>The Wotan class continued the expectation that Germany could place a conspicuous, heavily armed flagship at the center of a surface formation. It broke with the idea that protection and very heavy guns defined such a ship.</p><p>Its finite missile magazine, escort dependence, and vulnerability to mass attack were recognized limits, not evidence that the design was secretly intended to fight as an American-style battleship.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"memory",title:"Memory and prestige",html:"<p>The gun ships embodied wartime victory, industrial endurance, and the political ambitions of the old surface establishment. The Wotan class embodied a later claim: guidance, sensors, networks, and conventional missiles could sustain visible German oceanic power without rebuilding the armored battle line.</p><p>This distinction remained central to foreign classification debates and to German arguments over whether the surface service had escaped or merely adapted to submarine primacy.</p>"}
    ],
    related:[{href:"wotan-class.html",kicker:"Missile successor",label:"Wotan Class"},{href:"german-surface-fleet.html",kicker:"Fleet context",label:"German Surface Fleet"},{href:"kriegsmarine-postwar.html",kicker:"Service history",label:"Postwar Kriegsmarine"}],
    facts:[["Pre-divergence loss","Bismarck · 27 May 1941"],["Inherited Bismarck-class ship","Tirpitz"],["Other inherited capital ships","Scharnhorst · Gneisenau"],["H-39-derived completion","Friedrich der Große · 1947"],["Separate Yamato-scale project","Großdeutschland · 1949"],["Fixed retirement sequence","Tirpitz 1968 · Friedrich der Große 1972 · Großdeutschland 1975"],["Successor category","Large guided-weapon ship"],["New postwar battleship class","None"]],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/H-class_battleship_proposals",label:"Wikipedia — pre-divergence H-class design history"}]
  }),

  "german-carrier-force": navalArticle({
    title:"German aircraft-carrier force",
    category:"Naval aviation",
    landscape:fleetLandscape,
    lead:"The German aircraft-carrier force was a deliberately limited naval-aviation institution that connected wartime experimentation to the missile-network Kriegsmarine. <em>Graf Zeppelin</em> preserved the prewar carrier project; the new post-divergence <em>Peter Strasser</em> was conceived around future turbine aircraft; and the <em>Europa</em> class supplied the two registered active light carriers of 1985. German carriers provided reconnaissance, fighter cover, anti-submarine aviation, strike, and political presence without becoming the fleet's principal destructive arm.",
    canon:"The distinct origins of <em>Graf Zeppelin</em> and <em>Peter Strasser</em>, the latter's jet-oriented design requirement, the limited-carrier settlement, the <em>Europa</em>-class roster and commissioning years, registered displacements and standard air-group totals, and the two-carrier 1985 force are established.<sup class='canon-note' data-provenance='a'>[a]</sup> The older claim that <em>Peter Strasser</em> necessarily commissioned in 1947 is reopened; her final commissioning and retirement dates, aircraft types, detailed refits, and operational cruises remain open.<sup class='canon-note' data-provenance='e'>[e]</sup>",
    sections:[
      {id:"origins",title:"Wartime origins",html:"<p><a href='graf-zeppelin-and-peter-strasser.html'><em>Graf Zeppelin</em></a> was the suspended prewar hull returned to construction after divergence. <em>Peter Strasser</em> was not the resurrected historical Carrier B; she was a new design ordered in the divergent war and shaped by the expectation that turbine aircraft would reach the fleet.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>Together they created the yards, deck crews, maintenance trades, landing-signal practice, aviation logistics, and officer constituency required for a permanent carrier arm.</p>"},
      {id:"strasser",title:"The Peter Strasser requirement",html:"<p><em>Peter Strasser</em> emphasized stronger launch and recovery machinery, deck structure, elevators, fuel handling, and maintenance provision for heavier, faster aircraft. Her innovation was not the invention of the catapult but the attempt to make a German carrier useful across the piston-to-jet transition.</p><p>The current corpus places her at least far enough advanced by the postwar settlement to constitute a major naval investment, but no longer fixes a 1947 commissioning date.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"exchange",title:"Wartime technical exchange",html:"<p>Japanese carrier experience informed German deck organization, air-group handling, and operational cycles. German work on catapult machinery and turbine-aircraft launch requirements offered a reciprocal contribution.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>The exchange did not make the two navies doctrinal copies. Japan built carrier aviation as the fleet's decisive striking system; Germany used it to extend the reconnaissance, fighter, and command envelope of a submarine-centered force.</p>"},
      {id:"first-generation",title:"First-generation limitations",html:"<p><em>Graf Zeppelin</em> remained rooted in a prewar design. <em>Peter Strasser</em> answered the jet problem more directly, but early turbine aircraft still imposed severe launch weight, landing speed, fuel, maintenance, and deck-cycle penalties.</p><p>Exact air groups and refits remain open. The secure conclusion is institutional: Germany learned to operate carriers without concluding that it should build a Japanese-scale carrier fleet.</p>"},
      {id:"europa",title:"Europa-class light carriers",html:"<p><a href='europa-class-light-carrier.html'><em>Europa</em> and <em>Hansa</em></a> commissioned in 1962 and 1966. Each displaced 34,000 tonnes full load in the register and carried a standard thirty-six-aircraft group. German classification retained them as light carriers despite their size.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>The class replaced the wartime generation with ships designed from the outset for mature jet and helicopter operations.</p>"},
      {id:"air-groups",title:"Air-group functions",html:"<p>Carrier fighters protected the fleet and its reconnaissance aircraft. Helicopters and fixed-wing patrol aircraft contributed to antisubmarine screens, contact localization, and route clearance. Strike aircraft could attack ships or shore targets, but the air group also existed to find and classify targets for weapons launched elsewhere.</p><p>Exact aircraft marks and squadron allocations remain open.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"network",title:"Place in the reconnaissance network",html:"<p>A carrier could move sensors and fighters beyond the reach of shore bases, confirm satellite or signals contacts, and maintain a local picture for cruisers and submarines. That role made even a small carrier institution valuable to a fleet dependent upon distributed targeting.</p><p>German naval aviation consequently placed unusual weight on finding, classifying, tracking, and relaying rather than treating every aircraft primarily as a bomb carrier.</p>"},
      {id:"employment",title:"Task-group employment",html:"<p>A carrier normally operated with cruiser or large guided-weapon command support, destroyer air defense, frigate antisubmarine protection, and submarines screening ahead or covering likely hostile routes. The carrier widened the group's field of view while the surface missile ships complicated air defense.</p><p>This arrangement remained dependent on replenishment, trained deck crews, suitable weather, and protection from concentrated hostile carrier aviation.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"transition",title:"Generational transition",html:"<p>The old register places <em>Graf Zeppelin</em>'s retirement in 1972. The former 1975 date for <em>Peter Strasser</em> depends upon the reopened commissioning chronology and is therefore not treated as fixed. Personnel and experience nevertheless passed into the <em>Europa</em> class during a period of overlap.</p><p>That transfer, rather than continuous four-carrier readiness, explains how a small institution preserved technical continuity.</p>"},
      {id:"1985",title:"Position in 1985",html:"<p><em>Europa</em> and <em>Hansa</em> formed the complete registered active carrier force in 1985. Their value lay in organic reconnaissance, fighter cover, and helicopter aviation. Land-based aircraft, missiles, mines, and submarines carried the larger strategic burden.</p><p>Later German supercarrier development is authorially indicated, but its class identity, date, and relationship to the 1985 pair remain open pending a firmer register.</p>"}
    ],
    related:[{href:"graf-zeppelin-and-peter-strasser.html",kicker:"Wartime generation",label:"Graf Zeppelin and Peter Strasser"},{href:"europa-class-light-carrier.html",kicker:"Postwar class",label:"Europa-class Light Carrier"},{href:"german-surface-fleet.html",kicker:"Fleet context",label:"German Surface Fleet"},{href:"german-submarine-force.html",kicker:"Principal naval arm",label:"German Submarine Force"},{href:"wotan-class.html",kicker:"Command partner",label:"Wotan Class"}],
    facts:[["First carrier","Graf Zeppelin · 1945 register"],["Jet-oriented wartime design","Peter Strasser · commissioning open"],["Postwar class","Europa and Hansa"],["Europa-class commissioning","1962; 1966"],["Active in 1985","2"],["Standard Europa air group","36 aircraft"],["Strategic role","Limited fleet aviation and reconnaissance support"]],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/German_aircraft_carrier_Graf_Zeppelin",label:"Wikipedia — pre-divergence Graf Zeppelin design and construction"}]
  }),

  "graf-zeppelin-and-peter-strasser": navalArticle({
    title:"Graf Zeppelin and Peter Strasser",
    category:"Aircraft-carrier development",
    eyebrow:"German wartime carrier generation · 1941–1970s",
    landscape:fleetLandscape,
    lead:"<em>Graf Zeppelin</em> and <em>Peter Strasser</em> formed Germany's wartime carrier generation but were not identical sister ships. <em>Graf Zeppelin</em> was the suspended prewar hull returned to construction after divergence and registered as commissioning in 1945. <em>Peter Strasser</em> was a new post-divergence carrier conceived around the expected arrival of turbine aircraft, with stronger launch, recovery, deck, elevator, fuel, and maintenance arrangements. Their combined institutional legacy made a permanent German carrier arm possible.",
    canon:"<em>Graf Zeppelin</em>'s prewar origin, return to construction, 1945 registered commission, mature 35,000-tonne and forty-eight-aircraft entry, and 1972 retirement are established.<sup class='canon-note' data-provenance='a'>[a]</sup> <em>Peter Strasser</em>'s identity as a new post-divergence, jet-oriented design is established, but the earlier treatment of her as an identical 1947-commissioned sister is superseded; her final commissioning, displacement, air group, and retirement remain open.<sup class='canon-note' data-provenance='e'>[e]</sup>",
    sections:[
      {id:"zeppelin-origin",title:"Graf Zeppelin before divergence",html:"<p><em>Graf Zeppelin</em> began as Germany's prewar carrier project and was incomplete when the setting diverged on 1 August 1941. Her inherited hull, machinery, internal arrangement, and design assumptions made her the quickest route to an operational carrier, but also fixed many limitations before Germany possessed wartime deck-aviation experience.</p><p>Pre-divergence construction history is inherited; later completion and service belong to the divergent record.<sup class='canon-note' data-provenance='p'>[p]</sup></p>"},
      {id:"resumption",title:"Return to construction",html:"<p>Japanese naval-air victories and Germany's renewed maritime requirements strengthened the case for completing the suspended ship. Work did not instantly create an operational air group: pilots, deck crews, maintenance trades, landing control, magazines, aviation fuel, and escort doctrine had to mature with the hull.</p><p>The current class register places <em>Graf Zeppelin</em>'s commissioning in 1945.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
      {id:"strasser-origin",title:"A new Peter Strasser",html:"<p>The historical Carrier B had been abandoned before divergence. The setting's <em>Peter Strasser</em> was therefore a new wartime order, not a surviving second prewar hull. That distinction allowed the Navy to incorporate combat information and anticipated turbine-aircraft requirements rather than repeat the older design.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>She could belong to the same institutional generation without constituting a mechanically identical class.</p>"},
      {id:"jet",title:"Jet-oriented design requirement",html:"<p><em>Peter Strasser</em> was conceived around heavier aircraft with higher landing speeds and demanding launch acceleration. Stronger catapults, arresting gear, landing structure, elevators, fuel systems, and maintenance spaces formed the core distinction from <em>Graf Zeppelin</em>.</p><p>The catapult itself was not novel. The design problem was to make launch and recovery architecture robust enough for the piston-to-turbine transition.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
      {id:"exchange",title:"German–Japanese exchange",html:"<p>Japanese experience contributed practical knowledge of carrier air groups, deck cycles, spotting, and operational concentration. German engineers contributed work on catapults and on launching aircraft whose early turbine engines produced poor low-speed acceleration.</p><p>This exchange supported distinct national doctrines. Japan pursued carrier-centered striking power; Germany developed a smaller aviation arm in service of reconnaissance, defense, and distributed attack.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
      {id:"register",title:"Registered and reopened characteristics",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Ship</th><th>Origin</th><th>Secure register</th><th>Reopened field</th></tr></thead><tbody><tr><td><em>Graf Zeppelin</em></td><td>Prewar hull resumed after divergence</td><td>Commissioned 1945; mature register 35,000 t full load and 48 aircraft; retired 1972</td><td>Detailed refits and operational cruises</td></tr><tr><td><em>Peter Strasser</em></td><td>New post-divergence jet-oriented design</td><td>Major wartime/postwar investment</td><td>Commissioning, displacement, air group, retirement, and final design</td></tr></tbody></table></div><p>The former combined 35,000-tonne, forty-eight-aircraft class entry is not applied automatically to the structurally distinct second ship.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"training",title:"Institutional formation",html:"<p>The ships' most durable product was an aviation establishment: embarked squadrons, deck and hangar crews, landing officers, aviation engineering, weapons handling, carrier-qualified pilots, and shore training. Without that system, a flight deck was only an expensive transport surface.</p><p>German carrier practice remained small enough for individual ships and training bottlenecks to matter disproportionately.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"missions",title:"Postwar missions",html:"<p>The wartime-generation carriers supplied reconnaissance, fighter cover, strike, and antisubmarine aviation while newer methods matured. They supported surface groups and protected the approaches through which submarines and logistics forces deployed.</p><p>Neither ship established a requirement to contest Japan or the United States through carrier numbers. Their justification lay in organic aviation that land bases could not always provide.</p>"},
      {id:"transition",title:"Transition to the Europa class",html:"<p>The <a href='europa-class-light-carrier.html'>Europa class</a> replaced the first generation with ships designed from the outset around mature jet and helicopter operations. <em>Graf Zeppelin</em> retired in 1972. <em>Peter Strasser</em>'s retirement chronology remains open because the revised corpus no longer fixes her commissioning sequence.</p><p>Personnel, procedures, and shore infrastructure could transfer even where individual equipment could not.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"open-record",title:"Open ship records",html:"<p><em>Graf Zeppelin</em>'s wartime air group, jet refits, combat cruises, yards, and final disposition are not yet registered. <em>Peter Strasser</em>'s launch, commission, dimensions, propulsion, aircraft complement, refits, service history, and retirement require a dedicated authorial ledger.</p><p>The fixed distinction is conceptual: one ship completed a prewar project; the other began a German carrier design line adapted to the jet age.</p>"}
    ],
    related:[{href:"german-carrier-force.html",kicker:"Parent institution",label:"German Carrier Force"},{href:"europa-class-light-carrier.html",kicker:"Postwar successor",label:"Europa-class Light Carrier"},{href:"german-surface-fleet.html",kicker:"Fleet context",label:"German Surface Fleet"},{href:"german-capital-ships-postwar.html",kicker:"Parallel heavy-ship transition",label:"German Capital Ships after 1947"}],
    facts:[["Ships","Graf Zeppelin · Peter Strasser"],["Relationship","Same institutional generation; not identical sisters"],["Graf Zeppelin commission","1945 register"],["Graf Zeppelin mature entry","35,000 t · 48 aircraft"],["Graf Zeppelin retirement","1972"],["Peter Strasser design","New post-divergence · jet-oriented"],["Peter Strasser dates","Open"]],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/German_aircraft_carrier_Graf_Zeppelin",label:"Wikipedia — inherited pre-divergence design and construction history"}]
  }),

  "europa-class-light-carrier": navalArticle({
    title:"Europa-class light carrier",
    category:"Warship class",
    eyebrow:"German light carrier · Europa and Hansa · 1962–",
    landscape:fleetLandscape,
    lead:"The Europa class is a two-ship class of German light aircraft carriers comprising <em>Europa</em> and <em>Hansa</em>. Commissioned in 1962 and 1966, the 34,000-tonne ships carried standard thirty-six-aircraft groups and formed the complete registered active German carrier force in 1985. They were designed to provide reconnaissance, fighter cover, antisubmarine aviation, strike, and task-group support within a Navy whose principal offensive arm remained the submarine.",
    canon:"The two-ship roster, commissioning years, 34,000-tonne full-load displacement, standard thirty-six-aircraft air group, light-carrier classification, active 1985 status, and limited support doctrine are established.<sup class='canon-note' data-provenance='a'>[a]</sup> Dimensions, propulsion, speed, crew, aircraft types, squadron organization, deck arrangement, sensors, defensive armament, refits, yards, and individual deployments remain open.",
    sections:[
      {id:"requirement",title:"Postwar requirement",html:"<p>The wartime carrier generation proved that Germany could sustain deck aviation but also exposed the cost of adapting inherited hulls to jets and helicopters. The successor needed to preserve the institution with fewer ships while integrating the aviation, command, and maintenance demands of the postwar air group.</p><p>The requirement remained bounded: Germany sought useful organic aviation, not numerical parity with the Japanese or American carrier fleets.</p>"},
      {id:"classification",title:"Light-carrier classification",html:"<p>At 34,000 tonnes full load, the class was comparable in displacement to many earlier fleet carriers. German classification nevertheless treated it as a light carrier because the registered air group numbered thirty-six and because the ship served a supporting rather than mass-strike doctrine.</p><p>The label described institutional position as much as physical size.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"design",title:"Registered design",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Characteristic</th><th>Registered value</th></tr></thead><tbody><tr><td>Ships</td><td><em>Europa</em>; <em>Hansa</em></td></tr><tr><td>Full-load displacement</td><td>34,000 t</td></tr><tr><td>Standard air group</td><td>36 aircraft</td></tr><tr><td>Classification</td><td>Light aircraft carrier</td></tr><tr><td>1985 status</td><td>Both active</td></tr></tbody></table></div>"},
      {id:"aviation",title:"Aviation architecture",html:"<p>A purpose-built postwar carrier required reinforced landing areas, modern arresting gear, assisted launch, aircraft elevators, jet-compatible fuel and fire protection, and hangar maintenance for both fixed-wing aircraft and helicopters. These are systems-level implications rather than a fixed deck-plan claim.<sup class='canon-note' data-provenance='e'>[e]</sup></p><p>The exact number and arrangement of catapults, elevators, deck angles, and parking positions remain open.</p>"},
      {id:"air-group",title:"Air-group functions",html:"<p>The thirty-six-aircraft standard group balanced fleet fighters, reconnaissance or strike aircraft, and helicopters. Its exact composition changed with mission and period and has not been registered by aircraft mark.</p><p>Fighter cover protected the formation; reconnaissance extended the targeting network; helicopters supported antisubmarine search and rescue; strike aircraft supplied an organic attack option without replacing submarine or surface-missile fire.</p>"},
      {id:"ships",title:"Ships in class",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Ship</th><th>Commissioned</th><th>Status, 1985</th></tr></thead><tbody><tr><td><em>Europa</em></td><td>1962</td><td>Active</td></tr><tr><td><em>Hansa</em></td><td>1966</td><td>Active</td></tr></tbody></table></div><p>The four-year interval may have allowed equipment and production changes, but no distinct subclasses or per-ship refit standards are established.</p>"},
      {id:"reconnaissance",title:"Reconnaissance and targeting",html:"<p>The class extended the fleet's detection-and-attack chain beyond shore-based coverage. Embarked aircraft could investigate uncertain contacts, identify formations, maintain tracks, and relay targeting data to cruisers or submarines.</p><p>This reconnaissance function was central because long-range German missiles required current target information, and because a concealed submarine could not attack a force it had not located.</p>"},
      {id:"task-group",title:"Task-group employment",html:"<p>An Europa-class carrier normally depended upon a missile-cruiser or large guided-weapon command ship, destroyer air defense, frigate antisubmarine protection, and submarines operating ahead or on likely hostile routes. The carrier provided the group's movable aviation base rather than acting as an isolated striking fleet.</p><p>Amphibious support, Atlantic barriers, surface reconnaissance, and political presence were additional established mission categories.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
      {id:"maintenance",title:"Crew and maintenance system",html:"<p>Carrier availability depended on more than the hull. Pilots, deck crews, aviation engineers, ordnance teams, landing officers, controllers, spare engines, and shore qualification facilities formed a single readiness system.</p><p>With only two active ships, a major refit or training shortage could reduce available deck aviation sharply. Exact crews, air-wing establishments, and maintenance cycles remain open.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"1985",title:"Position in 1985",html:"<p>Both ships remained active on 1 January 1985 and constituted the complete registered German carrier arm. Their combined standard capacity was seventy-two aircraft, although that arithmetic does not establish embarked strength or readiness on a particular day.</p><p>The pair gave Germany a durable carrier institution and meaningful organic aviation, but not the massed deck-air power of the principal Pacific carrier navies.</p>"},
      {id:"open-record",title:"Open class record",html:"<p>Builders, laid-down and launch dates, dimensions, propulsion, speed, range, crew, sensors, defensive weapons, aircraft types, refits, deployments, accidents, and later service remain unregistered. Later German supercarrier development is indicated in the authorial corpus but cannot yet be connected to a named class or date.</p>"}
    ],
    related:[{href:"german-carrier-force.html",kicker:"Parent institution",label:"German Carrier Force"},{href:"graf-zeppelin-and-peter-strasser.html",kicker:"Wartime predecessor",label:"Graf Zeppelin and Peter Strasser"},{href:"wotan-class.html",kicker:"Heavy command partner",label:"Wotan Class"},{href:"admiral-scheer-class.html",kicker:"Cruiser partner",label:"Admiral Scheer Class"},{href:"german-surface-escorts.html",kicker:"Escort screen",label:"German Surface Escorts"}],
    facts:[["Ships","Europa · Hansa"],["Commissioned","1962 · 1966"],["Full-load displacement","34,000 t"],["Standard air group","36 aircraft each"],["Classification","Light aircraft carrier"],["Active in 1985","2"],["Combined standard capacity","72 aircraft"]]
  }),

  "wotan-class": navalArticle({
    title:"Wotan-class large guided-weapon ship",
    category:"Warship class",
    eyebrow:"Große Lenkwaffenschiffe · Wotan and Siegfried · 1978–",
    landscape:fleetLandscape,
    lead:"The Wotan class is a two-ship class of nuclear-electric <em>Große Lenkwaffenschiffe</em> operated by the Kriegsmarine. <em>Wotan</em> commissioned in 1978 and <em>Siegfried</em> in 1982 as the visible apex of Germany's missile-network surface fleet. Their command spaces, long-range air defense, conventional land-attack weapons, helicopters, and ninety-six-cell battery supported a submarine-centered fleet; official doctrine did not classify them as battleships.",
    canon:"The two-ship roster, commissioning years, 28,000-tonne full-load displacement, nuclear-electric propulsion, four 150 mm guns, ninety-six missile cells, three helicopters, extensive command spaces, conventional land attack, long-range air defense, electronic warfare, splinter protection, and <em>Großes Lenkwaffenschiff</em> classification are established.<sup class='canon-note' data-provenance='a'>[a]</sup> Dimensions, speed, crew, reactor count, armor scheme beyond splinter protection, exact missile families, sensors, refits, and individual deployments remain open.",
    sections:[
      {id:"requirement",title:"Requirement",html:"<p>The retirement of <em>Großdeutschland</em> in 1975 left the surface arm without a heavy command centerpiece, but it did not restore a requirement for battleship armor and very heavy guns. By then Germany possessed naval nuclear propulsion, submerged vertical-launch experience, long-range guided weapons, helicopters, and digital combat direction.</p><p>The requirement combined those systems in one ship able to sustain a task-group headquarters, defend a wide airspace, and threaten ships and shore targets while remaining useful to the undersea-centered fleet.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
      {id:"politics",title:"Institutional politics",html:"<p>Surface officers had spent the postwar era justifying major construction in a navy whose strategic prestige belonged to submarines. Wotan was their most ambitious answer: a ship large enough to command and display, yet built around functions the Dönitz settlement considered operationally defensible.</p><p>The second ship's commissioning four years later indicates that the concept survived initial service without establishing a requirement for a numerous class.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"classification",title:"Classification",html:"<p>The class was designated <em>Großes Lenkwaffenschiff</em>, or large guided-weapon ship. The term acknowledged an unusually large command-and-missile combatant without presenting it as a successor battleship.</p><p>Foreign tables sometimes placed the ships beside battleships or battlecruisers because of displacement and political effect. German classification instead emphasized weapons, command, and fleet function.</p>"},
      {id:"design",title:"Registered design",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Characteristic</th><th>Registered value</th></tr></thead><tbody><tr><td>Full-load displacement</td><td>28,000 t</td></tr><tr><td>Propulsion</td><td>Nuclear-electric</td></tr><tr><td>Gun battery</td><td>Four 150 mm guns</td></tr><tr><td>Vertical-launch capacity</td><td>96 cells</td></tr><tr><td>Aviation</td><td>Three helicopters</td></tr><tr><td>Protection</td><td>Splinter protection; full armor scheme open</td></tr></tbody></table></div>"},
      {id:"propulsion",title:"Nuclear-electric propulsion",html:"<p>Nuclear propulsion was exceptional in the German surface fleet. Submarines gained concealment and submerged endurance from a reactor; Wotan justified the cost through high continuous electrical demand, long-range command service, and independence from frequent propulsion-fuel replenishment.</p><p>Electric drive is consistent with the registered description and with the ship's sensor and combat-system load. Reactor count, plant topology, shaft arrangement, output, and speed remain open.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"weapons",title:"Missile and gun battery",html:"<p>Ninety-six vertical cells provided the class's defining battery. The established roles include long-range surface-to-air defense and conventional land attack; the proportion of those weapons, additional antiship or antisubmarine rounds, reload arrangements, and missile marks varied or remain unregistered.</p><p>Four 150 mm guns retained economical warning, bombardment, surface-action, and post-salvo firepower. They did not give the ship an American battleship's gun mission.</p>"},
      {id:"command",title:"Sensors, command, and electronic warfare",html:"<p>Large radar arrays and extensive command spaces made the class a theater-level surface node. It could assemble reports from ships, helicopters, aircraft, shore stations, and external reconnaissance; distribute tracks; allocate defensive engagements; and coordinate a surface formation with submarines operating beyond it.</p><p>Electronic warfare and splinter protection improved survival after detection. Exact arrays, frequencies, combat-system names, and redundancy standards remain open.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"aviation",title:"Aviation facilities",html:"<p>Three helicopters extended antisubmarine search, surface surveillance, targeting, liaison, and rescue beyond the ship's own horizon. The registered count does not establish one permanent aircraft type or mission mix.</p><p>Aviation helped convert the vessel from a missile magazine with a radar mast into a group command platform able to investigate and maintain distant contacts.</p>"},
      {id:"ships",title:"Ships in class",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Ship</th><th>Commissioned</th><th>Status, 1985</th><th>Registered significance</th></tr></thead><tbody><tr><td><em>Wotan</em></td><td>1978</td><td>Active</td><td>Lead ship; first nuclear-electric large guided-weapon ship</td></tr><tr><td><em>Siegfried</em></td><td>1982</td><td>Active</td><td>Second and final registered ship</td></tr></tbody></table></div>"},
      {id:"employment",title:"Operational employment",html:"<p>A Wotan-centered group could supply air defense, missile fire, aviation, communications, and command while presenting an overt threat that hostile forces had to track. German doctrine did not require the ship to close with an armored opponent. Its maneuver created opportunities for concealed attack and protected the escorts and carrier assets that sustained the wider operation.</p><p>The class could fire a major conventional salvo, but it could also achieve its purpose by forcing dispersal, defensive emissions, or a diversion of hostile aircraft.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"limits",title:"Magazine and survivability limits",html:"<p>The ninety-six-cell battery was finite and difficult to replenish at sea. Every launch reduced the available mix of defensive and offensive rounds, making allocation a command problem rather than an unlimited source of firepower.</p><p>No source establishes battleship armor or immunity to concentrated missile attack. The ships remained dependent upon destroyers, frigates, submarines, aircraft, replenishment, deception, and the larger sensor network.</p>"}
    ],
    related:[{href:"german-capital-ships-postwar.html",kicker:"Predecessor function",label:"German Capital Ships"},{href:"admiral-scheer-class.html",kicker:"Cruiser partner",label:"Admiral Scheer Class"},{href:"german-surface-escorts.html",kicker:"Escort screen",label:"German Surface Escorts"},{href:"german-carrier-force.html",kicker:"Aviation partner",label:"German Carrier Force"},{href:"german-surface-fleet.html",kicker:"Fleet context",label:"German Surface Fleet"}],
    facts:[["Ships","Wotan; Siegfried"],["Commissioned","1978; 1982"],["Full-load displacement","28,000 t"],["Propulsion","Nuclear-electric"],["Gun armament","Four 150 mm guns"],["Missile capacity","96 cells"],["Aviation","Three helicopters"],["Classification","Large guided-weapon ship"]]
  }),

  "admiral-scheer-class": navalArticle({
    title:"Admiral Scheer-class missile cruiser",
    category:"Warship class",
    eyebrow:"Missile cruiser · six ships · 1968–",
    landscape:fleetLandscape,
    lead:"The Admiral Scheer class is a six-ship class of German missile cruisers commissioned between 1968 and 1976. Combining four 150 mm guns, sixty-four vertical-launch cells, eight heavy anti-ship missiles, two helicopters, large radar arrays, and fleet-command facilities, the class became the routine centerpiece of German surface groups below the two Wotan-class large guided-weapon ships. Its 1974 public presentation exposed a surface expression of launch and guidance technology already used beneath the sea.",
    canon:"The six-ship roster, 1968–1976 commissioning band, 14,500-tonne full-load displacement, four 150 mm guns, sixty-four vertical cells, eight heavy anti-ship missiles, two helicopters, active 1985 status, command role, and 1974 public presentation are established.<sup class='canon-note' data-provenance='a'>[a]</sup> Per-ship commissioning dates, exact missile and sensor marks, dimensions, speed, crews, yards, refit calendars, and deployments remain open.",
    sections:[
      {id:"requirement",title:"Development requirement",html:"<p>The postwar surface fleet required a ship large enough to command a task group and carry substantial sensors, aviation, and guided weapons, but less politically and financially burdensome than a new capital ship. Destroyers could screen; they could not readily house the command staff and weapons volume expected of the group's center.</p><p>The resulting cruiser joined Germany's named-ship tradition to systems developed in the submarine missile program.</p>"},
      {id:"genealogy",title:"Submarine technological genealogy",html:"<p>Submerged launch forced German engineers to solve dense vertical storage, sealed-cell protection, ignition management, guidance initialization, and command-system integration before equivalent surface installations became public. The cruiser application was less constrained by pressure hulls but inherited that architecture.</p><p>The relationship did not make the ships surface submarines. It made them visible beneficiaries of an undersea research program whose operational extent remained classified.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"},
      {id:"presentation",title:"The 1974 presentation",html:"<p>The public presentation of <em>Admiral Scheer</em> in 1974 displayed vertical-launch and guidance capabilities to foreign observers. Analysts understood that related systems had already served aboard German guided-missile submarines for several years.<sup class='canon-note' data-provenance='a'>[a]</sup></p><p>The event was both a deliberate demonstration of surface power and an intelligence disclosure about the maturity of concealed German launch technology.</p>"},
      {id:"design",title:"Registered design",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Characteristic</th><th>Registered value</th></tr></thead><tbody><tr><td>Full-load displacement</td><td>14,500 t</td></tr><tr><td>Gun battery</td><td>Four 150 mm guns</td></tr><tr><td>Vertical-launch capacity</td><td>64 cells</td></tr><tr><td>Heavy anti-ship battery</td><td>Eight missiles</td></tr><tr><td>Aviation</td><td>Two helicopters</td></tr><tr><td>Commissioning band</td><td>1968–1976</td></tr></tbody></table></div>"},
      {id:"weapons",title:"Weapons architecture",html:"<p>The separate eight-round heavy anti-ship battery provided a declared surface-strike arm, while the sixty-four-cell installation could be configured around air-defense, land-attack, and other guided weapons as doctrine and availability required. Exact mixes and missile families remain open.</p><p>The 150 mm battery retained warning, bombardment, surface-action, and sustained-fire utility after expensive missiles were exhausted or inappropriate.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"sensors",title:"Command, sensors, and aviation",html:"<p>Large radar systems and command facilities allowed the cruiser to compile tracks, control the group's air-defense sectors, coordinate missile assignments, and relay contacts to other ships or submarines. Two helicopters extended local antisubmarine and surface search beyond the radar horizon.</p><p>The exact electronics fit evolved across a class commissioned over eight years, but no complete refit ledger is established.</p>"},
      {id:"ships",title:"Ships in class",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Ship</th><th>Commissioning</th><th>Status, 1985</th></tr></thead><tbody><tr><td><em>Admiral Scheer</em></td><td>Within 1968–76 band</td><td>Active</td></tr><tr><td><em>Prinz Eugen</em></td><td>Within 1968–76 band</td><td>Active</td></tr><tr><td><em>Lützow</em></td><td>Within 1968–76 band</td><td>Active</td></tr><tr><td><em>Blücher</em></td><td>Within 1968–76 band</td><td>Active</td></tr><tr><td><em>Seydlitz</em></td><td>Within 1968–76 band</td><td>Active</td></tr><tr><td><em>Admiral Hipper</em></td><td>Within 1968–76 band</td><td>Active</td></tr></tbody></table></div><p>Only the class-wide commissioning band is fixed; assigning individual years would create a false registry.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"employment",title:"Task-group employment",html:"<p>An Admiral Scheer-class ship normally supplied the command and area-defense center above a destroyer and frigate screen. Its helicopters investigated contacts, its radars organized the local picture, and its offensive weapons forced an opponent to maintain a surface-defense problem while German submarines approached.</p><p>The cruiser could lead an independent regional group, reinforce a Wotan formation, or protect a carrier, but it remained dependent upon escorts, external reconnaissance, and replenishment.</p>"},
      {id:"salvo",title:"Salvo and magazine management",html:"<p>Vertical launch offered rapid multi-weapon engagement and configuration flexibility, but each cell was a finite inventory. A commander had to preserve enough defensive rounds for the return passage while weighing the value of offensive salvos.</p><p>This constraint encouraged networked engagement: the cruiser did not need to fire at every track if aircraft, another escort, shore defenses, or a submarine held the better weapon or geometry.<sup class='canon-note' data-provenance='e'>[e]</sup></p>"},
      {id:"1985",title:"Position in 1985",html:"<p>All six ships remained active in the registered 1985 fleet. They formed the regular cruiser layer beneath <em>Wotan</em> and <em>Siegfried</em> and above the numbered destroyer and frigate classes.</p><p>Active status does not establish simultaneous readiness, identical refit state, or one permanent regional assignment.</p>"}
    ],
    related:[{href:"wotan-class.html",kicker:"Heavy command partner",label:"Wotan Class"},{href:"german-surface-fleet.html",kicker:"Fleet context",label:"German Surface Fleet"},{href:"german-surface-escorts.html",kicker:"Escort screen",label:"German Surface Escorts"},{href:"german-guided-missile-submarines.html",kicker:"Hidden technology predecessor",label:"German Guided-Missile Submarines"},{href:"german-guided-weapons-development.html",kicker:"Weapon lineage",label:"German Guided-Weapon Development"}],
    facts:[["Ships built","6"],["Commissioning band","1968–1976"],["Full-load displacement","14,500 t"],["Gun armament","Four 150 mm guns"],["Vertical cells","64"],["Heavy anti-ship missiles","8"],["Aviation","Two helicopters"],["Active in 1985","6"]]
  }),

  "german-surface-escorts": navalArticle({
    title:"German postwar surface escorts",
    category:"Warship development",
    landscape:fleetLandscape,
    lead:"German postwar surface escorts were the numbered destroyers, frigates, and fast missile craft that protected submarine access, carriers, cruisers, replenishment groups, bases, coastal waters, and <a href='german-mittelafrika-sea-communications.html'>the sea connection to Mittelafrika</a>. Their development moved from late-war gun and torpedo ships through missile conversion to digital vertical-launch fleet defense and long-range towed-array anti-submarine warfare.",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-se8pq writer=g kind=revision created=2026-08-16T08:23:53-06:00 -->The destroyer, frigate, and Schnellboot design sequence, role progression, and Z/F/S numbering conventions remain the working register.<sup class='canon-note' data-provenance='e'>[e]</sup> The revised naval audit withdraws exact German escort and fast-combatant build and 1985 active totals pending registry reconstruction; individual hulls, exact weapons, sensors, propulsion, yards, losses, exports, and refit histories also remain open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"destroyers",title:"Destroyer lineage",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-se9qr writer=g kind=revision created=2026-08-16T08:23:53-06:00 --><div class='table-wrap'><table class='wiki-table'><thead><tr><th>Class</th><th>Working introduction</th><th>Working full load</th><th>Role</th></tr></thead><tbody><tr><td>Typ 1944</td><td>1946–51</td><td>3,900 t</td><td>Late-war gun and torpedo destroyer</td></tr><tr><td>Typ 52</td><td>1953–61</td><td>4,800 t</td><td>First postwar missile-conversion hull</td></tr><tr><td>Typ 64</td><td>1965–72</td><td>5,900 t</td><td>Fleet air defense and surface attack</td></tr><tr><td>Typ 76</td><td>1977–84</td><td>7,100 t</td><td>Digital VLS fleet escort</td></tr></tbody></table></div><p>Build totals and active allocations are open.</p><!-- altwwii-writer-block:end -->"},
      {id:"frigates",title:"Frigate lineage",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-sf2st writer=g kind=revision created=2026-08-16T08:23:53-06:00 --><div class='table-wrap'><table class='wiki-table'><thead><tr><th>Class</th><th>Working introduction</th><th>Working full load</th><th>Role</th></tr></thead><tbody><tr><td>Typ 50</td><td>1951–58</td><td>2,500 t</td><td>Convoy and coastal escort</td></tr><tr><td>Typ 62</td><td>1963–71</td><td>3,300 t</td><td>ASW and general escort</td></tr><tr><td>Typ 74</td><td>1975–84</td><td>4,200 t</td><td>Quiet long-range towed-array escort</td></tr></tbody></table></div><p>Build totals and active allocations are open.</p><!-- altwwii-writer-block:end -->"},
      {id:"schnellboot",title:"Typ 73 Schnellboot",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-sf3tu writer=g kind=revision created=2026-08-16T08:23:53-06:00 --><p>The working register places 520-tonne Typ 73 fast combatants in service between 1973 and 1984 for missile ambush, coastal surveillance, base defense, and operations using shore-based sensors and short resupply routes. The exact number built and active in 1985 is open.</p><!-- altwwii-writer-block:end -->"},
      {id:"numbers",title:"Designation practice",html:"<p>Destroyers retain Z numbers, frigates F numbers, and fast combatants S numbers. Germany normally reserves personal names for carriers and cruiser-sized surface combatants.</p>"},
      {id:"doctrine",title:"Escort doctrine",html:"<p>Air defense, anti-submarine warfare, mine protection, electronic warfare, and replenishment security mattered because the U-boat fleet still required protected exits and support. The escorts did not merely screen prestige ships; they protected the infrastructure of submarine war.</p><p>Mittelafrika added a different obligation. Ocean frigates and destroyers had to escort merchant traffic, work with <a href='german-maritime-patrol-aviation.html'>maritime-patrol aircraft</a>, hand southern route sectors to the <a href='german-africa-naval-station.html'>African station</a>, and reinforce port approaches when a threat exceeded local patrol capacity.<sup class='canon-note' data-provenance='a'>[a]</sup></p>"}
    ],
    related:[{href:"german-surface-fleet.html",kicker:"Parent fleet",label:"German Surface Fleet"},{href:"german-submarine-force.html",kicker:"Protected arm",label:"German Submarine Force"},{href:"admiral-scheer-class.html",kicker:"Cruiser groups",label:"Admiral Scheer Class"},{href:"german-mittelafrika-sea-communications.html",kicker:"Convoy mission",label:"German–Mittelafrika Sea Communications"},{href:"german-africa-naval-station.html",kicker:"Southern route force",label:"German Africa Naval Station"},{href:"german-maritime-patrol-aviation.html",kicker:"Air-search partner",label:"German Maritime-Patrol Aviation"}],
    facts:[["Destroyer, frigate, and fast-combatant totals","<!-- altwwii-writer-block:start id=wb-g-20260816-sf4uv writer=g kind=revision created=2026-08-16T08:23:53-06:00 -->Open pending registry reconstruction<!-- altwwii-writer-block:end -->"],["Destroyer prefix","Z"],["Frigate prefix","F"],["Fast-combatant prefix","S"]]
  }),

  "german-submarine-force": navalArticle({
    title:"German submarine force, 1947–1985",
    category:"Submarine warfare",
    landscape:submarineLandscape,
    lead:"The German submarine force was the principal striking arm of the postwar Kriegsmarine and the world's leading submarine system in 1985. It joined the Type XXI submerged-operation inheritance to a fast school, a Stirling-AIP seabed-ambush school, nuclear Jagd-U-Boote, conventionally armed Lenkwaffen-U-Boote, and two transport branches.",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260815-g5r9b writer=g kind=revision created=2026-08-15T23:49:00-06:00 -->The working 1947 allocation, Type XXI foundation, Type XXVI and XXV fast-school work, Type XXIV and XXIX stealth/AIP school, Type XXX nuclear Jagd-U-Boot school, Type XXXI guided-missile school, conventional-only missile role, and transport branches are retained.<sup class='canon-note' data-provenance='a'>[a]</sup> The former Type XXI–XXXIV production ledger and exact forty-two-SSK, twenty-four-SSN, fourteen-SSGN, and eighty-boat 1985 totals are withdrawn; exact postwar construction, readiness, patrol zones, U-number assignments, weapons loads, and reactor specifications remain open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"inheritance",title:"The 1947 mass",html:"<p>The current working reconstruction has Germany commissioning 1,300 U-boats through 1947 and retaining 820 extant hulls, 310 of them front-line. The rest became a reservoir of crews, test beds, machinery, exports, training boats, reserve hulls, and scrap.</p>"},
      {id:"lineage",title:"Registered design schools",html:"<!-- altwwii-writer-block:start id=wb-g-20260815-k3v7m writer=g kind=revision created=2026-08-15T14:00:00-06:00 -->"+submarineTable+"<p>The register fixes the succession of ideas, not a complete postwar construction ledger. Nuclear power does not supersede AIP ambush boats, and neither branch erases the fast-school inheritance.</p><!-- altwwii-writer-block:end -->"},
      {id:"branches",title:"Combat branches",html:"<p><a href='german-conventional-submarine-line.html'>Conventional and AIP boats</a> cover general ocean operations, high-speed escort hunting, passive ambush, and seabed concealment. <a href='german-nuclear-attack-submarines.html'>Jagd-U-Boote</a> hunt ships and submarines with nuclear endurance. <a href='german-guided-missile-submarines.html'>Lenkwaffen-U-Boote</a> deliver conventional missiles against operational targets. <a href='german-submersible-transports.html'>Transport submarines</a> preserve minimum strategic sealift or move smaller high-value cargoes and specialists.</p>"},
      {id:"network",title:"The sensor and communications system",html:"<p>Satellites, patrol aircraft, signals stations, submarine transmitters, disguised maritime sensors, client reporting, and shore analysis converted contacts into patrol instructions. The network could cue a boat without continuously controlling it.</p><p>Its exact speed and reach were more secret than the existence of the boats themselves.</p>"},
      {id:"stealth",title:"Quieting and deception",html:"<p>Streamlined submerged hulls, anechoic tiles, machinery isolation, passive sonar, disciplined emissions, decoys, and repeated acoustic families complicated identification. Foreign crews could pass from one patrol zone to another and believe they had tracked one exceptional boat.</p>"},
      {id:"1985",title:"Front line in 1985",html:"<p>Germany fielded the world's leading submarine system, divided among fast, AIP ambush, nuclear attack, guided-missile, bulk-freight, and special-transport branches. Exact SSK/AIP, SSN, SSGN, transport, readiness, and deployment totals remain open pending a rebuilt registry.</p>"},
      {id:"limits",title:"Limits",html:"<p>No submarine could remain silent while communicating freely, and no network could classify every contact. Boats needed maintenance, weapons, trained crews, protected bases, and trustworthy intelligence.</p><p>German superiority created uncertainty and high costs for opponents; it did not make the Atlantic transparent to Berlin.</p>"}
    ],
    related:[{href:"elektroboot-heritage.html",kicker:"Design foundation",label:"Elektroboot Heritage"},{href:"german-conventional-submarine-line.html",kicker:"SSK branch",label:"Conventional Submarine Line"},{href:"german-nuclear-attack-submarines.html",kicker:"SSN branch",label:"Nuclear Jagd-U-Boote"},{href:"german-guided-missile-submarines.html",kicker:"SSGN branch",label:"Guided-Missile U-Boats"},{href:"german-submersible-transports.html",kicker:"Special branch",label:"Submersible Transports"}],
    facts:[["1947 extant boats","820 working"],["1947 front-line boats","310 working"],["First-line design schools","Fast · AIP ambush · nuclear attack"],["Missile school","Type XXXI and later derivatives"],["Transport branches","Unterseefrachter · Unterseetransportschiff"],["1985 totals","Open pending registry audit"],["Nuclear warheads","None"]]
  }),

  "elektroboot-heritage": navalArticle({
    title:"Elektroboot heritage of the Kriegsmarine",
    category:"Submarine development",
    landscape:submarineLandscape,
    lead:"The Elektroboot heritage was the design, industrial, and doctrinal inheritance of the Type XXI and Type XXIII submarines. It established the postwar German assumption that a submarine should be designed first for submerged movement, sensing, and attack rather than as a surface vessel able to dive temporarily.",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260816-v1n6b writer=g kind=revision created=2026-08-16T04:15:00-06:00 -->The Type XXI submerged-operation foundation, Type XXIII coastal branch, their 1944 introduction, working 1947 front-line allocation of 110 Type XXI and forty Type XXIII or related coastal Elektroboote, rapid postwar reduction, and influence on later design schools are direct setting canon.<sup class='canon-note' data-provenance='a'>[a]</sup> Their real-world design history begins after the 1 August 1941 divergence and therefore supplies reference context rather than inherited history.<sup class='canon-note' data-provenance='e'>[e]</sup> The former 184- and ninety-six-boat production totals, completion bands, 1985 status, individual hull histories, and exact postwar modifications remain open or withdrawn.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"origins",title:"Wartime design after the divergence",html:"<p>Type XXI combined a streamlined hull, large battery installation, snorkel, quiet-running motors, rapid torpedo handling, and sensors around primarily submerged operation. Type XXIII applied the Elektroboot idea to a much smaller coastal boat.</p><p>The current armament register introduces both types in 1944. Their design and production belong to the setting's extended war, not to inherited pre-divergence history.</p>"},
      {id:"production",title:"Armistice inheritance",html:"<!-- altwwii-writer-block:start id=wb-g-20260815-l6q2h writer=g kind=revision created=2026-08-15T14:00:00-06:00 --><p>The working 1947 allocation places 110 Type XXI and forty Type XXIII or related coastal Elektroboote in the front line. These are neither fixed campaign-audit totals nor complete production totals; the former 184-Type-XXI and ninety-six-Type-XXIII ledger is not retained as canon.</p><!-- altwwii-writer-block:end -->"},
      {id:"doctrine",title:"Doctrinal break",html:"<p>The designs made submerged speed, endurance, quiet approach, passive listening, and snorkel exposure central. They did not provide nuclear endurance or unlimited high speed, but they changed what German designers expected a submarine to be.</p>"},
      {id:"industry",title:"Industrial inheritance",html:"<p>Section construction, battery and motor production, pressure-hull yards, acoustic research, crew schools, torpedo systems, and base infrastructure survived victory. Quality problems in rushed wartime construction also became a postwar argument for tighter standards and test programs.</p>"},
      {id:"successors",title:"Successor schools",html:"<p>Type XXVI and Type XXV explored high submerged performance. Type XXIV A emphasized acoustic discipline and passive ambush, Type XXIV B inserted a Stirling AIP demonstrator, and Type XXIX matured the Lauerboot school. Type XXX joined nuclear endurance to fast-school hydrodynamics, while Type XXXI opened submerged conventional guided-missile attack.</p>"},
      {id:"retirement",title:"Institutional memory",html:"<p>The current register does not fix final Type XXI or Type XXIII retirement dates. Their enduring importance was institutional: later boats, training, foreign intelligence, export practice, and public mythology traced the modern U-boat arm to the Elektroboot generation.</p>"}
    ],
    related:[{href:"german-submarine-force.html",kicker:"Successor system",label:"German Submarine Force"},{href:"german-conventional-submarine-line.html",kicker:"Diesel-electric successors",label:"Conventional Submarine Line"},{href:"kriegsmarine-postwar.html",kicker:"Service history",label:"Postwar Kriegsmarine"}],
    facts:[["Type XXI front-line, 1947","110 working"],["Type XXIII and related front-line, 1947","40 working"],["Primary distinction","Designed for submerged operation"],["Postwar inheritance","Fast · AIP · nuclear · missile schools"],["Complete production totals","Open"],["Final retirement dates","Open"]],
    additionalSources:[{href:"https://en.wikipedia.org/wiki/German_Type_XXI_submarine",label:"Wikipedia — historical Type XXI design reference"},{href:"https://en.wikipedia.org/wiki/German_Type_XXIII_submarine",label:"Wikipedia — historical Type XXIII design reference"}]
  }),

  "german-conventional-submarine-line": navalArticle({
    title:"German conventional and AIP submarine schools",
    category:"Submarine development",
    landscape:submarineLandscape,
    lead:"Germany's postwar nonnuclear submarine development separated high submerged performance from extremely quiet ambush. Type XXVI and Type XXV informed the fast school; Type XXIV A established acoustic-discipline and passive-sensing practice; Type XXIV B demonstrated Stirling air-independent propulsion; and Type XXIX matured the seabed-ambush Lauerboot.",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260815-h7t3d writer=g kind=revision created=2026-08-15T23:49:00-06:00 -->The Type XXVI Walter escort hunter, Type XXV trial boat, Type XXIV A conventional stealth founder, Type XXIV B Stirling demonstrator, Type XXIX AIP Lauerboot, seabed-ambush doctrine, ordinary torpedo battery, specialized vertical quiet weapons, and complementarity with nuclear boats are established.<sup class='canon-note' data-provenance='a'>[a]</sup> The former Type XXIV/XXVII/XXIX/XXXII build ledger, forty-two-boat 1985 total, and associated active allocations are withdrawn; exact postwar construction totals remain open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"fast",title:"The fast school",html:"<p>Type XXVI was an elite, scarce, and technically secret Walter-powered escort hunter in 1945–47. Type XXV trials in 1946–47 explored a teardrop hull, extreme submerged sprint, and maneuverability, but battery endurance limited the concept. Its hydrodynamic lessons later informed nuclear Type XXX.</p>"},
      {id:"xxiv",title:"Type XXIV A and B",html:"<p>The <a href='type-xxiv-submarine.html'>Type XXIV A</a>, around 1951, made acoustic discipline, passive sensing, and ambush patrol the governing design priority. It remained diesel-electric and used its battery installation for the quietest patrol state. The Type XXIV B or <em>Versuch</em> work of about 1954–56 inserted a Stirling AIP plant and became the first German naval Stirling demonstrator.</p><p>The program established the stealth school before it possessed a purpose-designed AIP production hull. Exact Type XXIV construction, conversion, and service totals remain open.</p>"},
      {id:"xxix",title:"Type XXIX Lauerboot",html:"<!-- altwwii-writer-block:start id=wb-g-20260815-m9r5c writer=g kind=revision created=2026-08-15T14:00:00-06:00 --><p>The <a href='type-xxix-lauerboot.html'>Type XXIX</a>, developed around 1959–61, is a purpose-designed Stirling-AIP <em>Lauerboot</em>. It uses <em>Bodenlage</em> (bottoming) and <em>Schwebelage</em> (near-motionless suspension) to wait where a convoy must cross rather than pursue it across the ocean.</p><p>Routine first-generation bottoming is approximately 50–200 m. Strong structure, retractable broad-footed seabed supports, downward acoustic altimetry, approach controls, and sacrificial contact fittings support the mission; 700–900 m Norwegian-Trench work belongs to later development, not the first generation.</p><!-- altwwii-writer-block:end --><p>Hydrographic knowledge is part of the weapon system. Sediment, gradient, wrecks, cables, currents, seasonal sound-speed structure, and likely traffic determine whether a boat bottoms, hovers, or abandons a planned position.</p>"},
      {id:"weapons",title:"Concealment and weapons",html:"<p>Mineral-composite facing over elastomeric acoustic treatment complicates classification more than initial detection. Terrain, machinery silence, placement, and irregular background return remain necessary; a large low-frequency return cannot be removed by a thin exterior layer.</p><p>Ordinary horizontal torpedo tubes remain standard. Specialized vertical buoyant or low-powered weapons can attack a ship's underside from a static position and become one ancestor of German VLS, but do not replace the flexible torpedo battery. Quiet electric propulsion, passive homing, wire guidance, and influence fuzing serve the close ambush geometry.</p>"},
      {id:"missions",title:"Complementary roles",html:"<p><a href='lauerboot-doctrine.html'>A Lauerboot waits</a> where a convoy must cross; a Jagd-U-Boot searches for, pursues, or screens moving forces. Nuclear propulsion offers endurance and sustained repositioning, while AIP reduces snorkeling and machinery activity during a slow approach. At the final position, the AIP plant can also be shut down while essential loads run from batteries.</p><p>The branches share torpedoes, sensors, hydrographic intelligence, bases, and quieting research. Germany therefore retains both as first-line systems after the introduction of nuclear Type XXX.</p>"},
      {id:"countermeasures",title:"Antisubmarine response",html:"<p>Variable-depth and dipping sonar can search beneath unfavorable sound layers. Multistatic systems observe a bottom contact from separated geometries, while detailed bathymetric mapping and repeated passes reveal changes in the seabed. Patrol aircraft, mines, and surveillance of likely approach routes seek the boat before it reaches its prepared box.</p><p>These countermeasures prevent bottoming from becoming invisibility. The stealth school's objective is to delay classification, impose slow search, and obtain the first firing solution.</p>"},
      {id:"balance",title:"Open construction register",html:"<p>The current source fixes design schools and approximate first periods, not complete build or active totals. The former Type XXVII and Type XXXII allocations and the forty-two-boat 1985 SSK ledger are not retained pending a new registry audit.</p>"}
    ],
    related:[{href:"type-xxiv-submarine.html",kicker:"Stealth-school founder",label:"Type XXIV Submarine"},{href:"type-xxix-lauerboot.html",kicker:"Mature AIP ambush boat",label:"Type XXIX Lauerboot"},{href:"lauerboot-doctrine.html",kicker:"Operations",label:"Lauerboot Doctrine"},{href:"elektroboot-heritage.html",kicker:"Design ancestry",label:"Elektroboot Heritage"},{href:"german-nuclear-attack-submarines.html",kicker:"High-end complement",label:"Nuclear Jagd-U-Boote"},{href:"argentina.html",kicker:"Export customer",label:"Argentina"},{href:"german-submarine-force.html",kicker:"Parent arm",label:"German Submarine Force"}],
    facts:[["Fast-school ancestors","Type XXVI · Type XXV"],["Stealth-school founder","Type XXIV A · c. 1951"],["First Stirling demonstrator","Type XXIV B / Versuch · c. 1954–56"],["Mature AIP ambush boat","Type XXIX · c. 1959–61"],["Routine first-generation bottoming","Approximately 50–200 m"],["Postwar construction totals","Open"]]
  }),

  "german-nuclear-attack-submarines": navalArticle({
    title:"German nuclear attack submarines",
    category:"Submarine development",
    eyebrow:"Jagd-U-Boote · Type XXX school",
    landscape:submarineLandscape,
    lead:"German nuclear attack submarines, officially Jagd-U-Boote, began with the Type XXX school around 1962. The design joined nuclear endurance to Type XXV hydrodynamic experience and the quieting lessons of the conventional stealth branch, producing an ocean hunter distinct from the stationary AIP Lauerboot.",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260815-j2v6f writer=g kind=revision created=2026-08-15T23:49:00-06:00 -->Jagd-U-Boot terminology and hunting mission, the Type XXX founding generation around 1962, nuclear endurance, Type XXV hydrodynamic ancestry, quieting inheritance, torpedo-centered role, and absence of nuclear weapons are established.<sup class='canon-note' data-provenance='a'>[a]</sup> The former Type XXX and nuclear-Type-XXXIII build totals and twenty-four-SSN 1985 allocation are withdrawn; later class designations, construction totals, reactors, dimensions, speed, sensors, and patrol areas remain open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"concept",title:"Jagd-U-Boot concept",html:"<p>The attack branch sought ships and submarines rather than fixed land targets. Torpedoes remained the principal weapon; later secondary weapons and exact loads remain open.</p><p>Nuclear propulsion made long submerged patrols and high-speed repositioning possible; it did not make a boat silent at every speed.</p>"},
      {id:"xxx",title:"Type XXX",html:"<!-- altwwii-writer-block:start id=wb-g-20260815-n2c8v writer=g kind=revision created=2026-08-15T14:00:00-06:00 --><p>Type XXX, emerging around 1962, founded the nuclear Jagd-U-Boot school. It combined nuclear endurance with Type XXV hydrodynamic lessons and acoustic work inherited from the stealth branch. The current register does not fix a build total, service span, active count, or a numbered second generation.</p><!-- altwwii-writer-block:end -->"},
      {id:"later",title:"Later nuclear development",html:"<p>Germany retained a mature nuclear attack branch through 1985, but the source does not assign the old Type XXXIII nuclear identity. Type XXXIII appears elsewhere only as ancestry for an Argentine export SSK. Later German SSN designations and totals therefore remain open.</p>"},
      {id:"operations",title:"Operations",html:"<p>Attack boats screened guided-missile submarines, cleared routes for transports, hunted carrier and replenishment groups, watched hostile bases, and contested Atlantic barriers. They could also cue or receive information from the wider German sensor network.</p>"},
      {id:"balance",title:"Force in 1985",html:"<p>Nuclear Jagd-U-Boote formed one branch of the world's leading submarine system. Exact SSN construction, active strength, readiness, and patrol distribution remain open pending a rebuilt registry.</p>"},
      {id:"weapons",title:"No atomic mission",html:"<p>Neither class carried nuclear warheads because no nuclear arsenal existed. Their strategic importance came from conventional destruction, uncertainty, and the need they imposed upon every hostile carrier, convoy, and port approach.</p>"}
    ],
    related:[{href:"german-guided-missile-submarines.html",kicker:"Missile branch",label:"Guided-Missile U-Boats"},{href:"german-conventional-submarine-line.html",kicker:"Conventional complement",label:"German SSK Line"},{href:"german-submarine-force.html",kicker:"Parent arm",label:"German Submarine Force"}],
    facts:[["Official role name","Jagd-U-Boot"],["Founding school","Type XXX · c. 1962"],["Design inheritance","Type XXV hydrodynamics · stealth-school quieting"],["Principal weapon","Torpedo"],["1985 SSN total","Open"],["Later German designations","Open"],["Nuclear warheads","None"]]
  }),

  "german-guided-missile-submarines": navalArticle({
    title:"German guided-missile submarines",
    category:"Submarine development",
    eyebrow:"Lenkwaffen-U-Boote · Type XXXI and later derivatives",
    landscape:submarineLandscape,
    lead:"German guided-missile submarines, officially Lenkwaffen-U-Boote, began with Type XXXI in the late 1960s and continued through later derivatives. They carried conventional guided weapons for submerged operational bombardment against fleets, ports, airfields, fuel, communications, radar, and other military infrastructure rather than serving as atomic-deterrent ballistic-missile boats.",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260815-k4x8h writer=g kind=revision created=2026-08-15T23:49:00-06:00 -->The Lenkwaffen-U-Boot concept and target set, Type XXXI founding generation in the late 1960s, submerged conventional guided-missile attack, later derivatives, 1974 public disclosure through Admiral Scheer, and conventional-only weapons are established.<sup class='canon-note' data-provenance='a'>[a]</sup> The former Type XXXI/XXXIV build ledger, nuclear-propulsion assignment for every derivative, and fourteen-boat 1985 total are withdrawn; missile designations, cell counts, ranges, later class names, construction totals, targeting procedures, and patrol zones remain open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"concept",title:"Conventional operational bombardment",html:"<p>Without nuclear warheads, the missile boats attacked systems rather than cities as atomic hostages. A coordinated opening could damage naval bases, fuel, runways, radar, communications, headquarters, and concentrated ships before surface forces completed their response.</p>"},
      {id:"xxxi",title:"Type XXXI school",html:"<!-- altwwii-writer-block:start id=wb-g-20260815-p5h9q writer=g kind=revision created=2026-08-15T14:00:00-06:00 --><p>Type XXXI opened the concealed bombardment school in the late 1960s; the chronology places its first major operational generation in 1967. Later missile derivatives continued the branch, but the current register does not fix their class names, propulsion across every mark, construction totals, or 1985 allocation.</p><!-- altwwii-writer-block:end -->"},
      {id:"derivatives",title:"Later derivatives",html:"<p>The former Type XXXIV roster is not present in the controlling submarine register and is not retained as a fixed class. Later Type XXXI-derived SSGN development is established, with names, hull totals, and detailed specifications left open.</p>"},
      {id:"launch",title:"Submerged vertical launch",html:"<p>The boats could launch conventionally armed guided missiles from beneath the surface. Guidance, storage, and launch-control work remained classified until the 1974 presentation of the Admiral Scheer cruiser exposed related capabilities.</p>"},
      {id:"targeting",title:"Targeting network",html:"<p>Satellites, patrol aircraft, signals stations, maritime sensors, reconnaissance, and shore analysis supplied contacts and target updates. A missile boat could threaten a carrier group only when the system produced timely and accurate targeting.</p>"},
      {id:"uncertainty",title:"Intelligence problem",html:"<p>Foreign navies knew the class existed but could not reliably establish patrol state, load, readiness, conversion status, or location. The gap between knowing the weapon and locating the boat shaped Atlantic planning.</p>"},
      {id:"classification",title:"Classification",html:"<p>The absence of nuclear warheads prevents a strategic atomic SSBN mission. Some missile submarines may be nuclear-powered, but the current register fixes the submerged conventional-missile school more securely than a complete SSG/SSGN allocation.</p>"}
    ],
    related:[{href:"german-guided-weapons-development.html",kicker:"Weapon genealogy",label:"German Guided-Weapon Development"},{href:"admiral-scheer-class.html",kicker:"Public technology disclosure",label:"Admiral Scheer Class"},{href:"german-nuclear-attack-submarines.html",kicker:"Escort and hunting arm",label:"Nuclear Jagd-U-Boote"},{href:"german-submersible-transports.html",kicker:"Type XXXI conversions",label:"Submersible Transports"},{href:"iceland-crisis.html",kicker:"Atlantic confrontation",label:"Iceland Crisis"}],
    facts:[["Official role name","Lenkwaffen-U-Boot"],["Founding school","Type XXXI · late 1960s"],["First major operational generation","1967"],["Later development","Type XXXI-derived"],["Launch mode","Submerged guided-missile attack"],["1985 total","Open"],["Warheads","Conventional only"]]
  }),

  "german-submersible-transports": navalArticle({
    title:"German submersible transports",
    category:"Naval logistics",
    eyebrow:"Unterseefrachter and Unterseetransportschiffe · late 1950s–1985",
    landscape:submarineLandscape,
    lead:"German submersible transport doctrine divided between nuclear Unterseefrachter built to preserve minimum strategic sealift when <a href='german-mittelafrika-sea-communications.html'>the surface route to Mittelafrika</a> became unacceptable and smaller Unterseetransportschiffe for missiles, electronics, engines, medical stores, specialists, special forces, and deniable transfers. Neither branch could replace ordinary merchant shipping.",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260815-m6z2j writer=g kind=revision created=2026-08-15T23:49:00-06:00 -->Type XXVIII experiments in the late 1950s, the mature nuclear Unterseefrachter branch of the 1960s–80s, its 30,000–45,000-ton submerged scale and approximately 8,000-ton useful cargo, the smaller Unterseetransportschiff branch, Deutsche Ozeanische Reederei cover, and the Type XXXI/T and Type XXXV roles in Operation Nachtbrücke are established.<sup class='canon-note' data-provenance='a'>[a]</sup> The former small Type XXVIII/XXXI/T/XXXV class ledger, complete build totals, universal unarmed status, speeds, endurance, and 1985 allocation are withdrawn or open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"concept",title:"Purpose",html:"<p>Transport submarines did not replace merchant ships. Their payloads were tiny by commercial standards. They moved ammunition, missile seekers, radar parts, engines, sonar equipment, medical cargo, technicians, and other items whose arrival mattered more than volume.</p>"},
      {id:"types",title:"Two transport branches",html:"<!-- altwwii-writer-block:start id=wb-g-20260815-q8m4d writer=g kind=revision created=2026-08-15T14:00:00-06:00 --><div class='table-wrap'><table class='wiki-table'><thead><tr><th>Branch</th><th>Development</th><th>Normal purpose</th></tr></thead><tbody><tr><td>Unterseefrachter</td><td><a href='type-xxviii-cargo-submarine.html'>Type XXVIII</a> experiments in the late 1950s lead to a mature nuclear class in the 1960s–80s</td><td>Several-thousand-ton blockade-running loads preserving minimum strategic sealift to Mittelafrika</td></tr><tr><td>Unterseetransportschiff</td><td><a href='type-xxxi-t-submersible-transport.html'>Type XXXI/T</a> conversions and purpose-built <a href='type-xxxv-submersible-transport.html'>Type XXXV</a> transports</td><td>Missiles, electronics, engines, medical stores, technicians, special forces, and deniable transfers</td></tr></tbody></table></div><!-- altwwii-writer-block:end -->"},
      {id:"freighter",title:"Mature Unterseefrachter",html:"<p>The mature nuclear cargo submarine displaces roughly 30,000–45,000 tonnes submerged and carries a useful load on the order of 8,000 tonnes. Specialized surface-loading hatches and dedicated berths in Europe and Mittelafrika support cargo work. Several boats can load, transit, unload, and refit concurrently, but the exact class total remains open.</p>"},
      {id:"survival",title:"Survival doctrine",html:"<p>The Unterseefrachter normally surfaces for cargo operations and travels with one or two Jagd-U-Boote running ahead and abeam. Submergence protects it from gunfire and surface raiders, not submarines, mines, active sonar, or antisubmarine aviation. Exact defensive armament remains open.</p>"},
      {id:"cover",title:"Commercial cover",html:"<p>The <a href='deutsche-ozeanische-reederei.html'>Deutsche Ozeanische Reederei</a> provides civilian-commercial cover. Navy-built hulls, naval reservists, military navigation data, and classified tasking make the legal distinction fragile.</p>"},
      {id:"nachtbruecke",title:"Operation Nachtbrücke",html:"<p>In 1984 Germany and Argentina prepared <a href='operation-nachtbruecke.html'>Operation Nachtbrücke</a>, or Puente Sumergido, assigning one <a href='type-xxxi-t-submersible-transport.html'>Type XXXI/T</a> and one <a href='type-xxxv-submersible-transport.html'>Type XXXV</a> to covert supply through Puerto Belgrano and East Falkland. The Type XXXI/T completed three 650-tonne deliveries and the Type XXXV two 950-tonne deliveries, for 3,850 tonnes total.</p><p>The cargo emphasized missiles, ammunition, radar and sonar components, engines, medical supplies, communications equipment, lubricants, and technicians. It prolonged resistance without sustaining the whole garrison.</p>"},
      {id:"limits",title:"Limits",html:"<p>Even an eight-boat Unterseefrachter class would move only the equivalent of several ordinary Liberty-sized freighters per complete cycle. The branch made surface-route closure mean ruthless prioritization rather than immediate severance; it could not sustain all of Mittelafrika through an indefinite blockade.</p>"}
    ],
    related:[{href:"type-xxviii-cargo-submarine.html",kicker:"Experimental bulk-freight founder",label:"Type XXVIII Cargo Submarine"},{href:"type-xxxi-t-submersible-transport.html",kicker:"Converted special transport",label:"Type XXXI/T Transport"},{href:"type-xxxv-submersible-transport.html",kicker:"Purpose-built special transport",label:"Type XXXV Transport"},{href:"deutsche-ozeanische-reederei.html",kicker:"Commercial cover",label:"Deutsche Ozeanische Reederei"},{href:"german-guided-missile-submarines.html",kicker:"Type XXXI origin",label:"Guided-Missile U-Boats"},{href:"german-mittelafrika-sea-communications.html",kicker:"Principal blockade mission",label:"German–Mittelafrika Sea Communications"},{href:"german-africa-naval-station.html",kicker:"African receiving system",label:"German Africa Naval Station"},{href:"falklands-war.html",kicker:"1984 operational setting",label:"Falklands–Malvinas War"},{href:"argentina.html",kicker:"Operational partner",label:"Argentina"},{href:"kriegsmarine-postwar.html",kicker:"Parent service",label:"Postwar Kriegsmarine"}],
    facts:[["Transport branches","Unterseefrachter · Unterseetransportschiff"],["First postwar cargo submarine","Type XXVIII · 1959"],["Type XXXI/T conversions","2 begun · 1974"],["Type XXXV transports","2 commissioned · 1982–84"],["Mature freighter scale","30,000–45,000 t submerged"],["Working useful cargo","Approximately 8,000 t"],["Complete Unterseefrachter total","Open"],["Commercial cover","Deutsche Ozeanische Reederei"],["Named plan","Operation Nachtbrücke / Puente Sumergido"],["Nachtbrücke delivered","3,850 t"]]
  })
});
